example/samples/std_cli.mgl.code:
import std::cli;
int64 main(){
    CliParser parser;parser.program="demo";parser.description="sample tool";
    CliOption count;count.name="count";count.shortName='n';count.takesValue=true;count.defaultValue="3";count.description="number of items";
    CliOption verbose;verbose.name="verbose";verbose.shortName='v';
    CliOption output;output.name="output";output.shortName='o';output.takesValue=true;output.required=true;
    assert(parser.add(count) && parser.add(verbose) && parser.add(output) && !parser.add(count));
    List<String> args;args.push("-vn12");args.push("--output=result.txt");args.push("input.txt");args.push("--");args.push("-literal");
    CliArguments result=parser.parse(args).unwrap();
    assert(result.getInt("count").unwrap()==12 && result.get("verbose").unwrap()=="true");
    assert(result.get("output").unwrap()=="result.txt" && result.positional.len()==2 && result.positional[1]=="-literal");
    List<String> defaults;defaults.push("-o");defaults.push("out");assert(parser.parse(defaults).unwrap().getInt("count").unwrap()==3);
    List<String> bad;bad.push("--unknown");assert(!parser.parse(bad).isOk());
    List<String> missing;missing.push("-n");assert(!parser.parse(missing).isOk());
    List<String> help;help.push("--help");assert(parser.parse(help).unwrap().helpRequested);
    List<String> required;assert(!parser.parse(required).isOk());
    List<String> invalid;invalid.push("-oout");invalid.push("-nabc");assert(!parser.parse(invalid).unwrap().getInt("count").isOk());
    assert(len(parser.help())>40);
    println("CLI options, defaults and validation OK");return 0;
}

example/samples/std_math_clock_random.mg.code:
/* std_math_clock_random.mgl —— 第二档：Math 补齐、Clock、Random 扩展。
 *
 * 三条路线各不相同，改这块前先分清：
 *   * Math 的 float64 取整 / 判定走**宿主胶水**（glue/std_math.hpp 绑 <cmath>）；
 *   * Math 的 int64 版是**Magel 重载转发到宿主胶水**（写在同一模块里，实参完全匹配优先于 int64→float64 放宽）；
 *   * Clock 是宿主胶水（chrono 的 steady_clock）；
 *   * Random 的 nextRange / nextBool 是 宿主胶水的薄封装。
 *
 * `choice` / `shuffle` 不在 `Random::` 下：Magel 没有泛型方法，而 `std::random::Random` 这个
 * 名字已经被同名的 struct 占着（再开同名模块会让 `Random::withSeed` 找不到）。
 * 它们放在 `algorithms`，调用写 `std::algorithms::choiceValue<int64>(表, 种子)`。
 */

import std::random;

import std::math;
import std::algorithms;

import std::clock;

int64 main() {
    /* --- Math：float64 取整 / 取余 / 特殊值判定（宿主 <cmath>） --- */
    println("{} {} {} {}", std::math::floor(2.7), std::math::ceil(2.1),
    std::math::round(2.5), std::math::trunc(-2.7));
    println("{} {}", std::math::fmod(7.5, 2.0), std::math::fmod(-7.5, 2.0));

    /* Magel 里浮点除零是运行期错误，所以 NaN / Inf 从宿主函数拿：
     * sqrt(-1) = NaN、ln(0) = -Inf。 */
    float64 notNumber = std::math::sqrt(-1.0);
    float64 infinite = std::math::ln(0.0);
    println("{} {} {} {}", std::math::isNaN(notNumber), std::math::isNaN(1.0),
    std::math::isInf(infinite), std::math::isInf(1.0));

    /* --- Math：int64 版（Magel 重载转发到宿主胶水）+ float64 版 abs 仍然可用 --- */
    println("{} {} {} {}", std::math::abs(-5), std::math::min(3, 8),
    std::math::max(3, 8), std::math::clamp(12, 0, 10));
    println("{}", std::math::abs(-2.5));

    /* --- Clock：单调时钟。读数本身不可复现，只断言"拿到了、且不倒退"。 --- */
    int64 before = std::clock::nowNanos();
    int64 millis = std::clock::nowMs();
    int64 after = std::clock::nowNanos();
    println("{} {} {}", before > 0, millis > 0, after >= before);

    /* --- Random：分布 --- */
    std::random::Random rng = std::random::Random::withSeed((uint64)12345);
    float64 ranged = rng.nextRange(10.0, 20.0);
    int64 drawn = rng.nextInt(0, 10);
    bool coin = rng.nextBool();
    /* 固定种子 -> 固定序列（和 std_parse_random_path_memory 一个口径：钉住随机输出）。 */
    println("{} {} {}", ranged, drawn, coin);
    println("{} {}", ranged >= 10.0, ranged < 20.0);

    /* --- 取一个 / 洗一副（种子自己给，结果可复现） --- */
    List<int64> items;
    items.push(1);
    items.push(2);
    items.push(3);
    /* 种子 0：`0 % 3 == 0`，无论随机数怎么算都取到第 0 个。 */
    println("{}", std::algorithms::choiceValue<int64>(items, (uint64)0));

    List<int64> mixed = std::algorithms::shuffleValue<int64>(items, (uint64)4242);
    println("{} {} {}", mixed.len(),
    mixed[0] + mixed[1] + mixed[2],   /* 洗牌不改总和 */
    items[0]);                        /* 原表不动 */

    List<int64> again = std::algorithms::shuffleValue<int64>(items, (uint64)4242);
    println("{} {} {}", again[0] == mixed[0], again[1] == mixed[1],
    again[2] == mixed[2]);
    return 0;
}

example/samples/std_collections_algorith.code:
import std::collections;

import std::memory;

import std::algorithms;

bool positive(int64 value) { return value > 0; }
int64 addValues(int64 left, int64 right) { return left + right; }

int64 main() {
    List<int64> values;
    values.push(4);
    values.push(1);
    values.push(3);
    List<int64> sorted = std::algorithms::sortValue<int64>(values);
    println("{} {} {} {} {}", sorted[0], sorted[1], sorted[2],
    std::algorithms::binarySearchValue<int64>(sorted, 3),
    std::algorithms::foldValue<int64>(sorted, 0, addValues));
    println("{} {} {}", values[0], values[1], values[2]);

    List<float64> stableValues;
    stableValues.push(-0.0);
    stableValues.push(2.0);
    stableValues.push(0.0);
    stableValues.push(1.0);
    List<float64> stableSorted = std::algorithms::sortValue<float64>(stableValues);
    println("{1:1F} {2:1F} {3:1F} {4:1F}", stableSorted[0], stableSorted[1],
    stableSorted[2], stableSorted[3]);
    println("{} {} {} {} {}", std::algorithms::findValue<int64>(sorted, 4),
    std::algorithms::minValue<int64>(9, 2), std::algorithms::maxValue<int64>(9, 2),
    std::algorithms::clampValue<int64>(12, 0, 10),
    std::algorithms::allValue<int64>(sorted, positive));
    println("{} {} {} {}", std::algorithms::minValue<int64>(9, 2, 7, -1),
    std::algorithms::maxValue<int64>(9, 2, 12, 7),
    std::algorithms::minValue<int64>(5), std::algorithms::maxValue<int64>(6));

    std::collections::Deque<int64> deque = std::collections::Deque<int64>::create();
    deque.pushBack(2);
    deque.pushFront(1);
    println("{} {} {}", deque.len(), deque.popFront().unwrap(),
    deque.popBack().unwrap());

    std::collections::Queue<int64> queue = std::collections::Queue<int64>::create();
    queue.push(7);
    queue.push(8);
    println("{} {}", queue.peek().unwrap(), queue.pop().unwrap());

    std::collections::RingBuffer<int64> ring = std::collections::RingBuffer<int64>::withCapacity(2);
    println("{} {} {}", ring.push(5), ring.push(6), ring.push(7));
    println("{} {}", ring.pop().unwrap(), ring.available());

    std::collections::FixedVector<int64> fixed = std::collections::FixedVector<int64>::withCapacity(1);
    println("{} {} {}", fixed.push(9), fixed.push(10), fixed[0]);

    int64 raw[] = new[2];
    raw[0] = 11;
    raw[1] = 12;
    std::memory::Span<int64> span = std::memory::Span<int64>::from(&raw[0], len(raw));
    println("{} {} {}", span.len(), span[0], span[1]);

    std::collections::Channel<int64> channel = std::collections::Channel<int64>::create();
    channel.send(21);
    println("{} {}", channel.len(), channel.receive().unwrap());

    Pair<int64, String> pair = Pair<int64, String>::of(7, "seven");
    println("{} {}", pair.first, pair.second);
    delete raw;
    return 0;
}

