import std::memory;
import std::parse;
import std::path;
import std::random;

int64 main() {
    Result<int64, std::parse::ParseError> integer = std::parse::Parse::parseInt64("-42");
    Result<uint64, std::parse::ParseError> natural = std::parse::Parse::parseUInt64("18446744073709551615");
    Result<float64, std::parse::ParseError> real = std::parse::Parse::parseFloat64("12.5");
    Result<bool, std::parse::ParseError> flag = std::parse::Parse::parseBool("true");
    match (integer) {
        Result<int64, std::parse::ParseError>::Ok(value) => { println("int64={}", value); }
        Result<int64, std::parse::ParseError>::Err(error) => { println("int64=error"); }
    }
    match (natural) {
        Result<uint64, std::parse::ParseError>::Ok(value) => { println("uint64={}", value); }
        Result<uint64, std::parse::ParseError>::Err(error) => { println("uint64=error"); }
    }
    match (real) {
        Result<float64, std::parse::ParseError>::Ok(value) => { println("float64={:1F}", value); }
        Result<float64, std::parse::ParseError>::Err(error) => { println("float64=error"); }
    }
    match (flag) {
        Result<bool, std::parse::ParseError>::Ok(value) => { println("bool={}", (int64)value); }
        Result<bool, std::parse::ParseError>::Err(error) => { println("bool=error"); }
    }

    Result<int64, std::parse::ParseError> empty = std::parse::Parse::parseInt64("");
    Result<int64, std::parse::ParseError> invalid = std::parse::Parse::parseInt64("4x");
    Result<int64, std::parse::ParseError> overflow =
    std::parse::Parse::parseInt64("999999999999999999999999");
    match (empty) {
        Result<int64, std::parse::ParseError>::Ok(value) => { println("empty=bad"); }
        Result<int64, std::parse::ParseError>::Err(error) => {
            match (error) {
                std::parse::ParseError::Empty => { println("empty=ok"); }
                _ => { println("empty=bad"); }
            }
        }
    }
    match (invalid) {
        Result<int64, std::parse::ParseError>::Ok(value) => { println("invalid=bad"); }
        Result<int64, std::parse::ParseError>::Err(error) => {
            match (error) {
                std::parse::ParseError::Invalid => { println("invalid=ok"); }
                _ => { println("invalid=bad"); }
            }
        }
    }
    match (overflow) {
        Result<int64, std::parse::ParseError>::Ok(value) => { println("overflow=bad"); }
        Result<int64, std::parse::ParseError>::Err(error) => {
            match (error) {
                std::parse::ParseError::Overflow => { println("overflow=ok"); }
                _ => { println("overflow=bad"); }
            }
        }
    }

    std::random::Random first = std::random::Random::withSeed((uint64)7);
    std::random::Random second = std::random::Random::withSeed((uint64)7);
    uint64 firstValue = first.nextUInt64();
    uint64 secondValue = second.nextUInt64();
    assert(firstValue == secondValue);
    println("random={},{}", firstValue, first.nextInt(-10, 10));
    std::random::Random entropy = std::random::Random::fromEntropy();
    entropy.nextUInt64();

    String joined = std::path::PathString::join("alpha/beta", "../gamma.txt");
    String name = std::path::PathString::fileName("alpha/gamma.txt");
    String extension = std::path::PathString::extension("alpha/gamma.txt");
    String normalized = std::path::PathString::normalize("a\\b/./c/../d");
    println("path={}", joined);
    println("name={} ext={}", name, extension);
    println("normalized={}", normalized);

    int64 before = std::memory::Memory::stats().liveBytes;
    std::memory::Arena arena = std::memory::Arena::create();
    std::memory::Span<char> bytes = arena.allocate(16);
    assert(bytes.len() == 16);
    int64 during = std::memory::Memory::stats().liveBytes;
    assert(during >= before + 16);
    arena.reset();
    int64 after = std::memory::Memory::stats().liveBytes;
    assert(after <= during - 16);
    println("memory=ok");
    return 0;
}

example/samples/std_net.mgl.code:
/* std_net.mgl —— `std::net`（TCP + 极简 HTTP 客户端）用法样例。
 *
 *   ./magel samples/std_net.mgl
 *
 * 全程不需要外网、不需要第二个进程：
 *   1. 先在本进程里 listen（端口给 0 让系统分配）→ connect → accept，双向收发；
 *   2. 再单独测三个纯函数：地址解析、请求拼装、响应解析。
 *
 * 因此输出是确定的（端口号不打印）。套接字实现见 `glue/std_net.hpp`
 * （Windows 运行期加载 ws2_32.dll，POSIX 直接调用同名接口）。
 */

import std::net;

int64 main() {
    /* ---- 1. 回环 TCP：监听 / 连接 / 接受 / 收发 ---- */
    std::net::TcpListener listener = std::net::TcpListener::listen("127.0.0.1", (int32)0, (int32)8);
    println("listener open={} port>0={}", listener.isOpen(), listener.localPort() > 0);
    int64 port = listener.localPort();

    std::net::TcpSocket client = std::net::TcpSocket::connect("127.0.0.1", (int32)port, (int32)2000);
    std::net::TcpSocket peer = listener.accept((int32)2000);
    println("client open={} peer open={}", client.isOpen(), peer.isOpen());

    client.send("ping\n");
    String request = peer.receiveLine((int32)2000);
    println("server got [{}] status={}", request, peer.status());

    peer.send("pong\n");
    String reply = client.receiveLine((int32)2000);
    println("client got [{}] status={}", reply, client.status());

    peer.close();
    client.close();
    listener.close();
    println("closed client={} peer={} listener={}", client.isOpen(), peer.isOpen(), listener.isOpen());

    /* ---- 2. 纯函数：地址解析 / 请求拼装 / 响应解析 ---- */
    std::net::Url url = std::net::parseUrl("http://example.com:8080/a/b?c=1");
    println("url ok={} host={} port={} path={}", url.ok, url.host, url.port, url.path);
    std::net::Url bad = std::net::parseUrl("https://example.com/");
    println("https rejected={} error=[{}]", !bad.ok, bad.error);

    String get = std::net::buildRequest("GET", "http://example.com/x", "", "");
    println("GET request len={}", len(get));

    String raw = "HTTP/1.1 200 OK\r\nContent-Length: 5\r\nContent-Type: text/plain\r\n\r\nhello";
    std::net::HttpResponse response = std::net::parseResponse(raw);
    println("response ok={} status={} reason={} len={} type={} body={}",
    response.ok, response.status, response.reason,
    response.header("Content-Length"), response.header("content-type"), response.body);
    return 0;
}

example/samples/std_numerics_number_theo.code:
import std::linalg;
import std::numerics;
import std::numtheory;

import std::math;

float64 square(float64 x) { return x*x; }
float64 rootFunction(float64 x) { return x*x-2.0; }
float64 exponentialRate(float64 time, float64 value) { return value; }

int64 main() {
    std::linalg::Vector<float32> left=std::linalg::Vector<float32>::zeros(2);
    left.set(0,(float32)3.0); left.set(1,(float32)4.0);
    std::linalg::Vector<float32> right=left+left;
    std::linalg::Vector<float32> difference=right-left;
    std::linalg::Vector<float32> scaled=left*(float32)2.0;
    assert(difference.at(0)==(float32)3.0 && scaled.at(1)==(float32)8.0);
    std::linalg::Matrix<float32> matrix=std::linalg::Matrix<float32>::identity(2);
    std::linalg::Matrix<float32> doubled=matrix+matrix;
    std::linalg::Matrix<float32> recovered=doubled-matrix;
    std::linalg::Matrix<float32> scaledMatrix=matrix*(float32)3.0;
    std::linalg::Vector<float32> mapped=doubled*left;
    assert(mapped.at(0)==(float32)6.0 && mapped.at(1)==(float32)8.0);
    assert(recovered.at(1,1)==(float32)1.0 && scaledMatrix.at(0,0)==(float32)3.0);
    std::linalg::Matrix<float32> product=matrix*matrix;
    assert(product.at(0,0)==(float32)1.0);

    float64 integral=std::numerics::Numerics::integrateSimpson(square,0.0,1.0,20);
    float64 slope=std::numerics::Numerics::derivative(square,2.0,0.0001);
    float64 root=std::numerics::Numerics::bisect(rootFunction,1.0,2.0,0.00000001,100);
    float64 newton=std::numerics::Numerics::newton(rootFunction,1.0,0.00000001,20);
    List<float64> euler=std::numerics::Numerics::solveOdeEuler(exponentialRate,0.0,1.0,0.1,10);
    List<float64> rk4=std::numerics::Numerics::solveOdeRK4(exponentialRate,0.0,1.0,0.1,10);
    assert(std::math::abs(integral-1.0/3.0)<0.00001);
    assert(std::math::abs(slope-4.0)<0.00001);
    assert(std::math::abs(root-std::math::sqrt(2.0))<0.000001);
    assert(std::math::abs(newton-std::math::sqrt(2.0))<0.000001);
    assert(euler.len()==11 && rk4.len()==11);
    assert(rk4.at(10)>euler.at(10) &&
    std::math::abs(rk4.at(10)-std::math::E)<0.00001);

    assert(std::numtheory::gcd((uint64)54,(uint64)24)==6);
    assert(std::numtheory::lcm((uint64)6,(uint64)8)==24);
    assert(std::numtheory::modInverse((int64)3,(int64)11)==4);
    assert(std::numtheory::modInverse((int64)-3,(int64)11)==7);
    assert(std::numtheory::powMod((uint64)7,(uint64)128,(uint64)97)==35);
    assert(std::numtheory::isPrime((uint64)97));
    assert(!std::numtheory::isPrime((uint64)561));
    uint64 largePrime=(uint64)2305843009213693951;
    assert(largePrime==(((uint64)1<<61)-1));
    assert(std::numtheory::mulMod(largePrime-1,largePrime-1,largePrime)==1);
    assert(std::numtheory::isPrime((uint64)65537));
    println("generic matrix numerics number theory OK");
    return 0;
}

